 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # A repeated-color rail on a border emits the other isolated color along
    # the rail's perpendicular axis. Existing cells of that emitted color
    # become the impact color 4.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    rails = []
    # contiguous runs along outer border, at least two cells, excluding background
    for r in (0, h - 1):
        c = 0
        while c < w:
            v = grid[r][c]
            e = c + 1
            while e < w and grid[r][e] == v:
                e += 1
            if v != bg and e - c >= 2:
                rails.append((r, c, e, v))
            c = e
    for c in (0, w - 1):
        r = 0
        while r < h:
            v = grid[r][c]
            e = r + 1
            while e < h and grid[e][c] == v:
                e += 1
            if v != bg and e - r >= 2:
                rails.append((c, r, e, v))
            r = e
    # The cells struck by emitted rays identify the color to spread.
    rail_colors = {x[3] for x in rails}
    target_colors = [v for v, n in counts.items() if v != bg and v not in rail_colors]
    if not target_colors:
        return out
    target = max(target_colors, key=lambda v: counts[v])
    for r, a, b, v in rails:
        if v not in rail_colors:
            continue
        # Horizontal border rails project parallel vertical columns.
        if r == 0 or r == h - 1:
            for c in range(a, b):
                for rr in range(h):
                    out[rr][c] = 4 if grid[rr][c] == target else target
        # Vertical border rails project parallel horizontal rows.
        else:
            col, arow, bend, _ = r, a, b, v
            for rr in range(arow, bend):
                for cc in range(w):
                    out[rr][cc] = 4 if grid[rr][cc] == target else target
    return out
