 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # Border bars are placed at opposite corners. Their projected bands are
    # bounded by the bar's endpoint coordinates and are filled with the
    # scattered interior color; collisions turn to 4.
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != background and end - c >= 2:
                bars.append((r, c, end, color))
            c = end
    barcolors = {b[3] for b in bars}
    target_colors = [v for v in counts if v != background and v not in barcolors]
    target = max(target_colors, key=lambda v: counts[v]) if target_colors else None
    if target is None:
        return out
    for edge, start, end, color in bars:
        # Mirror the bar's span across the grid: top edge fills to the left of
        # its segment, bottom edge fills to the right of its segment.
        if edge == 0:
            lo, hi = max(1, start - (end - start)), start
        else:
            lo, hi = end, min(w - 1, end + (end - start))
        for r in range(1, h - 1):
            for c in range(lo, hi):
                if grid[r][c] == target:
                    out[r][c] = 4
                elif grid[r][c] == background:
                    out[r][c] = target
    return out
