    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    # Find the two horizontal border bars of a common color.
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != background and end - c >= 2:
                bars.append((r, c, end, color))
            c = end
    interior = [(r, c) for r in range(h) for c in range(w)
                if grid[r][c] != background and (r, c) not in
                {(br, cc) for br, a, b, _ in bars for cc in range(a, b)}]
    if not interior:
        return out
    color_counts = {}
    for r, c in interior:
        color_counts[grid[r][c]] = color_counts.get(grid[r][c], 0) + 1
    fill = max(color_counts, key=color_counts.get)

    # Diagonal marker chain defines a wedge. At each row, fill through the
    # rightmost marker at or above it, leaving the chain as 4s.
    for r in range(1, h - 1):
        row_markers = [c for rr, c in interior if rr == r and grid[rr][c] == fill]
