 "content": "def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    # The border bars project their own color toward the opposite edge. A
    # sparse object encountered by a projected ray becomes 4, and stops it.
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    bars = []
    for r in (0, h - 1):
        c = 0
        while c < w:
            color = grid[r][c]
            end = c + 1
            while end < w and grid[r][end] == color:
                end += 1
            if color != bg and end - c >= 2:
                bars.append((r, c, end, color))
            c = end
    for r, c0, c1, color in bars:
        dr = 1 if r == 0 else -1
        for c in range(c0, c1):
            rr = r + dr
            while 0 < rr < h - 1:
                if grid[rr][c] != bg:
                    out[rr][c] = 4
                    break
                out[rr][c] = color
                rr += dr
    return out
